338:export async function editOpen(page: Page, personId: string): Promise<void> {
339-  await page.getByTestId(`person-edit-${personId}`).click();
340-  await expect(page.getByTestId('person-form-name')).not.toHaveValue('', { timeout: WAIT });
341-  editing.set(page, personId);
342-}
343-
344-/**
345- * Save the open editor with these changes; true when saved, false when the form refused. `shows` is
346- * the grade the row shows once saved: by default the grade entered, but a grade dated from another
347- * day may leave the grade in force on the sheet's today unchanged.
348- */
349-type Shows = string | { grade?: string; terms?: string };
350-
351:export async function editSave(page: Page, f: PersonFields, shows?: Shows): Promise<boolean> {
352-  const id = editing.get(page);
353-  if (!id) throw new Error('editSave without editOpen');
354-  const want = typeof shows === 'string' ? { grade: shows } : (shows ?? {});
355-  const grade = want.grade ?? f.grade;                       // the grade the row shows once saved
356-  const terms = want.terms ?? f.terms;                       // the terms in force the row shows
357-  await fillPersonForm(page, f);
358-  await page.getByTestId('person-form-submit').click();
359-  const r = row(page, id);
360-  return until(page, async () => {
361-    if (f.name !== undefined && plainName(await shown(r.getByTestId('person-name'))) !== f.name.trim()) return false;
362-    if (grade !== undefined && await shown(r.getByTestId('person-grade')) !== grade) return false;
363-    if (terms !== undefined && await shown(r.getByTestId('person-terms')) !== terms) return false;
364-    return !(await page.getByTestId('person-form-error').isVisible().catch(() => false));
365-  }, page.getByTestId('person-form-error'), 'save person');
366-}
