369-  await editOpen(page, personId);
370-  return editSave(page, f, shows);
371-}
372-
373-export async function retire(page: Page, personId: string, date: string): Promise<boolean> {
374-  const r = row(page, personId);
375-  const done = async () => (await r.count()) === 0 || await shown(r.getByTestId('person-retired')) === 'yes';
376-  const already = await done();
377-  await r.getByTestId('person-retire-date').fill(date);
378-  await r.getByTestId('person-retire').click();
379-  return until(page, done, r.getByTestId('person-error'), 'retire', already);
380-}
